<script lang="ts">
	import { MoreHorizontal, Plus, UserRound, X } from '@lucide/svelte';
	type User = { id: number; name: string; role: string; status: 'Active' | 'Disabled' };
	let users = $state<User[]>([{ id: 1, name: 'sahil', role: 'Administrator', status: 'Active' }, { id: 2, name: 'morgan', role: 'User', status: 'Active' }, { id: 3, name: 'riley', role: 'User', status: 'Disabled' }]);
	let addOpen = $state(false);
	let disableUser = $state<User | null>(null);
	let newName = $state('');
	let created = $state('');
	function addUser() { if (newName.trim()) { users = [...users, { id: Date.now(), name: newName.trim(), role: 'User', status: 'Active' }]; created = newName.trim(); newName = ''; addOpen = false; } }
	function disable() { if (disableUser) { users = users.map((user) => user.id === disableUser?.id ? { ...user, status: 'Disabled' } : user); disableUser = null; } }
</script>
<section class="page">
	<div class="heading-row"><div class="page-heading"><p class="eyebrow">Administration</p><h2>Users</h2><p>Manage ordinary library accounts. This view uses synthetic local fixture data.</p></div><button class="text-action" onclick={() => (addOpen = true)}><Plus size={17} /> Add user</button></div>
	<div class="user-list" aria-label="Users">
		{#each users as user}
			<article class="user-row"><div class="user-icon"><UserRound size={18} /></div><div class="user-copy"><strong>{user.name}</strong><span>{user.role}</span></div><span class:disabled={user.status === 'Disabled'} class="status">{user.status}</span>{#if user.name !== 'sahil'}<button class="icon-action" aria-label={`Actions for ${user.name}`} onclick={() => (disableUser = user)}><MoreHorizontal size={19} /></button>{:else}<span class="spacer"></span>{/if}</article>
		{/each}
	</div>
</section>
{#if addOpen}<div class="backdrop"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="add-title"><button class="close" aria-label="Close dialog" onclick={() => (addOpen = false)}><X size={18} /></button><h3 id="add-title">Add user</h3><p>Create an ordinary user account. Admin role changes are not available.</p><form onsubmit={(event) => { event.preventDefault(); addUser(); }}><label>Username<input bind:value={newName} required /></label><label>Initial password<input type="password" required /></label><label>Your current password<input type="password" required /></label><button class="text-action primary" type="submit">Create user</button></form></div></div>{/if}
{#if disableUser}<div class="backdrop"><div class="dialog" role="dialog" aria-modal="true" aria-labelledby="disable-title"><button class="close" aria-label="Close dialog" onclick={() => (disableUser = null)}><X size={18} /></button><h3 id="disable-title">Disable {disableUser.name}?</h3><p>Access will be revoked for this user. Confirm with the admin's current password.</p><label>Current password<input type="password" /></label><div class="dialog-actions"><button class="text-action" onclick={() => (disableUser = null)}>Cancel</button><button class="text-action danger" onclick={disable}>Disable user</button></div></div></div>{/if}
{#if created}<p class="created" role="status">User “{created}” added to the local fixture.</p>{/if}
<style>
	.page { max-width: 680px; } .heading-row { display: flex; align-items: end; justify-content: space-between; gap: 20px; } .page-heading h2 { margin: 0; font-size: 24px; letter-spacing: -.04em; } .page-heading p:last-child { margin: 8px 0 0; color: var(--color-text-secondary); line-height: 1.6; } .eyebrow { margin: 0 0 10px; color: var(--color-text-disabled); font-size: 12px; letter-spacing: .14em; text-transform: uppercase; }
	.user-list { display: grid; gap: 4px; margin-top: 40px; } .user-row { display: grid; grid-template-columns: 40px 1fr auto 44px; gap: 12px; align-items: center; min-height: 64px; } .user-icon { display: grid; width: 36px; height: 36px; place-items: center; border-radius: 11px; background: var(--color-input); color: var(--color-text-secondary); } .user-copy { display: grid; gap: 3px; } .user-copy span, .status { color: var(--color-text-secondary); font-size: 12px; } .status.disabled { color: var(--color-text-disabled); } .icon-action, .close { display: grid; min-width: 44px; min-height: 44px; place-items: center; border: 0; background: transparent; color: var(--color-text-secondary); cursor: pointer; } .icon-action:hover, .close:hover { color: var(--color-text-primary); } .text-action { display: inline-flex; min-height: 44px; align-items: center; gap: 8px; border: 0; background: transparent; padding: 8px 0; color: var(--color-text-primary); cursor: pointer; } .text-action:hover { opacity: .72; } .primary { margin-top: 10px; font-weight: 600; } .danger { color: var(--color-danger); } .backdrop { position: fixed; inset: 0; z-index: 20; display: grid; place-items: center; padding: 20px; background: #0008; } .dialog { position: relative; width: min(100%, 420px); border-radius: 16px; background: var(--color-elevated); padding: 24px; box-shadow: 0 18px 50px #0008; } .close { position: absolute; top: 12px; right: 12px; } .dialog h3 { margin: 0; font-size: 18px; } .dialog p { color: var(--color-text-secondary); line-height: 1.6; } form { display: grid; gap: 14px; margin-top: 22px; } label { display: grid; gap: 7px; color: var(--color-text-secondary); font-size: 13px; } input { min-height: 44px; border: 0; border-radius: 9px; background: var(--color-input); padding: 10px 12px; color: var(--color-text-primary); } .dialog-actions { display: flex; justify-content: flex-end; gap: 18px; margin-top: 20px; } .created { color: var(--color-text-secondary); font-size: 13px; }
	@media (max-width: 599px) { .heading-row { align-items: start; flex-direction: column; } .user-row { grid-template-columns: 40px 1fr auto; } .user-row .icon-action { grid-column: 3; grid-row: 1; } .status { grid-column: 2; } }
</style>
